  str_n34_dispatch_task_5_log_8 = "6,2 horas na investigação\nDuvido que os Eclipsitas já imaginaram que os Aurorianos passariam por este pântano. Nossos desafios são apenas as ameaças naturais imediatas. Acabou o acampamento, pessoal - vamos continuar seguindo em frente.",
  str_n34_dispatch_task_5_log_9 = "8 horas na investigação\nTodo o pântano! Quase me afogou!",
  str_n34_dispatch_task_5_log_10 = "8,2 horas na investigação\nRevy acabou de ficar presa no pântano. Quando a tiramos de lá, ela estava encharcada da cabeça aos pés. Mas Gram decidiu continuar seguindo em frente! Vamos torcer para que seu instinto esteja certo desta vez.",
  str_n34_dispatch_task_5_log_11 = "9,5 horas na investigação\nFinalmente saí dessa confusão! Até comecei a sentir falta da Linha Dunafogo.",
