  str_n34_dispatch_task_6_log_2 = "1,2 horas na investigação\nO terreno à frente é inquietante, com um campo de visão estreito. Todos, mantenham-se vigilantes e cuidado com emboscadas de Eclipsitas.",
  str_n34_dispatch_task_6_log_3 = "2 horas de investigação\nEssas colunas... estão cobertas de gelo espesso, refletindo a luz como espelhos. É quase transparente... Não baixem a guarda, equipe.",
