  str_n34_dispatch_task_6_log_6 = "7 horas na investigação\nA luz está muito fraca! Não podemos usar o sol ou as estrelas para navegação. Então temos que recorrer a... maquinaria?",
  str_n34_dispatch_task_6_log_7 = "7,5 horas na investigação\nImprovisamos uma bússola improvisada usando um relógio. Vamos sair deste morro gelado primeiro.",
