  str_n34_dispatch_task_2_com_7 = "Posso ouvir um som insuportável e estridente se eu usar isso para limpar a arma.",
  str_n34_dispatch_task_2_com_8 = "Parece que você está sendo incomodado por água impura. Câmbio.",
