  str_n34_dispatch_task_4_com_3 = "Meu cabelo todo arrepiado... Está tão frio.",
  str_n34_dispatch_task_4_com_4 = "Colocamos nosso equipamento à prova de frio e já estamos vestidos com eles. Câmbio.",
  str_n34_dispatch_task_4_com_5 = "E quanto à ponte de pedra? E como você vai voltar de lá? Câmbio.",
  str_n34_dispatch_task_4_com_6 = "A ponte de pedra é uma rocha naturalmente erodida. A corda de segurança foi firmemente fixada. Até mesmo Revy não escorregou ao caminhar por aqui. Acabou.",
