  str_n34_dispatch_task_4_com_12 = "Seu moral está elevado. O caminho à frente será mais difícil, cuide da sua saúde e suprimentos. Informe se houver alguma emergência. Câmbio.",
  str_n34_dispatch_task_4_com_13 = "Sim!",
  str_n34_dispatch_task_5_com_1 = "Tosse... Gram está reportando, Grande Marechal. Câmbio.",
  str_n34_dispatch_task_5_com_2 = "E a sua condição? Você consegue persistir? Acabou.",
  str_n34_dispatch_task_5_com_3 = "Estou em Illumina há anos, mas esta é a primeira vez que vejo um terreno tão estranho. É frio e úmido, mas a camada de gelo aqui é tão fina! Acho que vou trazer o pessoal do Laboratório de Pesquisa para cá. Acabou.",
  str_n34_dispatch_task_5_com_4 = "Com base na minha experiência, deve haver impurezas invisíveis na água, então ela não congela facilmente.",
  str_n34_dispatch_task_5_com_5 = "A Chefe de Inteligência está certa. Não devemos pegar água do pântano, a menos que seja uma emergência. Câmbio.",
  str_n34_dispatch_task_5_com_6 = "Mas eu engoli um pouco. Talvez eu tenha me engasgado com o líquido quando estava preso no pântano, e agora meu estômago dói.",
  str_n34_dispatch_task_5_com_7 = "Eu verifiquei a condição dela. Revy só ingeriu um pouco, e acho que o mal-estar não veio da água, mas do espasmo causado pelo frio e pela umidade. Podemos pressionar o abdômen dela para aliviar a dor.",
  str_n34_dispatch_task_5_com_8 = "Vamos fazer isso! Revy, nós vamos te pressionar com toda a nossa força!",
  str_n34_dispatch_task_5_com_9 = "Estou aqui! É só mirar em mim!",
  str_n34_dispatch_task_5_com_10 = "Montamos nosso acampamento e estamos descansando agora.",
  str_n34_dispatch_task_5_com_11 = "Finalmente, peixe seco e água fervida... Se ao menos houvesse uma xícara de café...",
  str_n34_dispatch_task_5_com_12 = "Que tal eu tratar todos vocês depois que voltarmos? Minha ração é abundante e com certeza vocês terão todo o café ou peixe seco que quiserem.",
  str_n34_dispatch_task_5_com_13 = "Beleza!",
  str_n34_dispatch_task_5_com_14 = "Não sou especialmente fã de café.",
  str_n34_dispatch_task_5_com_15 = "May Eu peço peixes secos sortidos agora?",
  str_n34_dispatch_task_5_com_16 = "Parece que Chandra desempenha um papel importante, Gram.",
  str_n34_dispatch_task_5_com_17 = "Sim, Grande Marechal.",
  str_n34_dispatch_task_6_com_1 = "Grande Marechal aqui. Qual é a sua condição? Câmbio.",
  str_n34_dispatch_task_6_com_2 = "Grande Marechal aqui. Por favor, responda se você pode me ouvir. Câmbio.",
  str_n34_dispatch_task_6_com_3 = "Foi tão perigoso! O gelo estava todo como espelhos.",
  str_n34_dispatch_task_6_com_4 = "Espelhos? O que você quer dizer?",
  str_n34_dispatch_task_6_com_5 = "Eles prejudicariam nosso senso de direção, tornando a marcha muito mais difícil do que o normal. Até nossa visão se tornou pouco confiável lá.",
  str_n34_dispatch_task_6_com_6 = "Não tenho certeza do que você está dizendo, por favor explique. Sobre.",
  str_n34_dispatch_task_6_com_7 = "Aqui. Gram está reportando, Grande Marechal.",
  str_n34_dispatch_task_6_com_8 = "Passamos por uma área montanhosa. A inclinação era suave, mas o terreno era imprevisível e cheio de pilares de pedra cobertos de gelo.",
  str_n34_dispatch_task_6_com_9 = "Por isso, marchamos em uma floresta de pilares de pedra. Nossa visão era bloqueada por eles, e nossos sentidos também eram perturbados pela luz refletida no gelo. Ficaríamos tontos e até perderíamos o caminho se permanecêssemos lá por muito tempo.",
  str_n34_dispatch_task_6_com_10 = "Se fôssemos afetados severamente, perderíamos nossas mentes e mergulharíamos na loucura.",
  str_n34_dispatch_task_6_com_11 = "Realmente parece perigoso... Então, como você conseguiu sair dessa situação?",
  str_n34_dispatch_task_6_com_12 = "Graças ao conselho de Benny and Curo. Montamos um dispositivo para nos orientar usando meu relógio, o cabo de aço na arma de Revy e a polia em nosso equipamento de acampamento.",
  str_n34_dispatch_task_6_com_13 = "O dispositivo funcionava como uma bengala. Usamos para sondar o terreno à nossa frente e, assim que nos afastamos da direção anterior, o dispositivo indicava o ângulo em que viramos.",
  str_n34_dispatch_task_6_com_14 = "Embora não fosse muito preciso, era melhor do que nada. Quanto ao gelo deslumbrante, Chandra sugeriu que mantivéssemos nossas cabeças baixas ao marchar.",
  str_n34_dispatch_task_6_com_15 = "Mas e se fôssemos atacados pelos Eclipsitas? Nem teríamos tempo de sacar nossas armas!",
  str_n34_dispatch_task_6_com_16 = "Não importa. Todos eles seriam tratados.",
  str_n34_dispatch_task_6_com_17 = "De qualquer forma, saímos. Agora estamos perto da fronteira com a noite eterna. Acabou.",
  str_n34_dispatch_task_6_com_18 = "Fique de olho na condição da equipe e não se esforce demais. Recue se necessário. Cambio.",
  str_n34_dispatch_task_7_com_1 = "Chandra, Chandra! Qual é a sua condição? Câmbio.",
  str_n34_dispatch_task_7_com_2 = "Sem vítimas. Retornamos. Câmbio.",
  str_n34_dispatch_task_7_com_3 = "Conte-me brevemente o que você viu ao longo do caminho. Câmbio.",
  str_n34_dispatch_task_7_com_4 = "Uma caverna escura como breu! Com um teto alto e um espaço enorme!",
  str_n34_dispatch_task_7_com_5 = "E vento.",
  str_n34_dispatch_task_7_com_6 = "E isso pode afetar a luz dentro dele. Só conseguiríamos ver alguns passos à frente, mesmo se acendêssemos a melhor lâmpada.",
  str_n34_dispatch_task_7_com_7 = "O ar fétido tornava difícil respirar, e as pessoas facilmente se perdiam por lá.",
  str_n34_dispatch_task_7_com_8 = "Vou te contar o que aconteceu em seguida, Grande Marechal.",
  str_n34_dispatch_task_7_com_9 = "Recebi seu relatório. Câmbio.",
  str_n34_dispatch_task_7_com_10 = "Esperávamos que eles voltassem em 1 hora, mas não voltaram mesmo depois de esperarmos mais uma hora. Então entrei na caverna para encontrá-los. Acabou.",
  str_n34_dispatch_task_7_com_11 = "Quais suprimentos você tinha? Câmbio.",
  str_n34_dispatch_task_7_com_12 = "Comida e água para 7 dias, armas, equipamento à prova de frio, uma lâmpada para um dia inteiro de iluminação, ferramentas de escalada, cordas de segurança e um galão de combustível. Acabou.",
  str_n34_dispatch_task_7_com_13 = "Você não levou o dispositivo de direção com você? Câmbio.",
  str_n34_dispatch_task_7_com_14 = "Os colegas de equipe no acampamento precisariam disso para guiá-los através dos desagradáveis pilares de pedra se eu não pudesse voltar. Acabou.",
  str_n34_dispatch_task_7_com_15 = "Você é um bom capitão. Continue. Sobre.",
  str_n34_dispatch_task_7_com_16 = "Assim como fizemos antes, mantive minha cabeça baixa e me concentrei nas pegadas deles no chão. Marquei algumas pegadas borradas com pitons de escalada e, depois que acabei com eles, cortei um pedaço da minha corda e mergulhei-a no combustível para marcar as pegadas pouco claras. Acabou.",
  str_n34_dispatch_task_7_com_17 = "O combustível pode atrair Eclipsitas. Uma escolha arriscada, mas você provou estar certo. Acabou.",
  str_n34_dispatch_task_7_com_18 = "Não podemos sempre contar com a nossa sorte, Grande Marechal. Atualmente, chegamos ao ponto mais distante em nossa exploração na noite eterna. Câmbio.",
  str_n34_dispatch_task_7_com_19 = "Volte agora. Abandone alguns suprimentos, se necessário. Câmbio.",
  str_n34_dispatch_task_7_com_20 = "Yes, Grand Marshal. Over.",
  str_n34_dispatch_task_7_com_21 = "Tenha cuidado e garanta a segurança do pessoal em primeiro lugar. Eu vou esperar por você no Crepúsculo. Câmbio.",
  str_n34_dispatch_task_7_com_22 = "Vejo você lá, Grande Marechal. Câmbio."
}
return config
